-- ============================================================
-- SEED EXT 2: Módulo 21 — Inversion (exercícios 71-165)
-- Novos tópicos: so/such...that inversion, little/in no way/
-- at no time, neither/nor, academic register, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'inversion';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo inversion não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: so + adjective + inversion
  (cid,11,71,'gap_fill','So significant _____ the discovery _____ it transformed the entire field overnight.','was / that',NULL,'"So + adjective + was + subject + that..." = emphatic inversion with so.','hard'),
  (cid,11,72,'multiple_choice','Which sentence uses "so...that" inversion correctly?','So profound was the impact of the Industrial Revolution that it altered every aspect of daily life.','["So profound the impact of the Industrial Revolution was that it altered every aspect.","So profound was the impact of the Industrial Revolution that it altered every aspect of daily life.","So profound is the impact of the Industrial Revolution that it altered every aspect.","The Industrial Revolution''s impact was so profound that it altered every aspect."]','So + adjective + inverted auxiliary + subject + that-clause.','hard'),
  (cid,11,73,'gap_fill','So ___ (rapid) was the spread of the virus that containment proved impossible within weeks.','rapid',NULL,'"So rapid was the spread that..." = inversion. Adjective follows "so."','medium'),
  (cid,11,74,'multiple_choice','Transform: "The evidence was so compelling that the court overturned the verdict." → inverted form.','So compelling was the evidence that the court overturned the verdict.','["So compelling the evidence was that the court overturned the verdict.","So was the evidence compelling that the court overturned the verdict.","So compelling was the evidence that the court overturned the verdict.","The evidence so compelling was that the court overturned."]','"So + adjective + was + subject + that" = standard inversion pattern.','hard'),
  (cid,11,75,'gap_fill','So ___ (complex) _____ the regulatory framework _____ many small businesses struggled to comply.','complex / was / that',NULL,'"So complex was the regulatory framework that..." = emphatic inversion.','hard'),
  (cid,11,76,'multiple_choice','Which sentence uses SUCH for inversion?','Such was the scale of the devastation that international aid organizations struggled to respond.','["Such the scale of the devastation was that international aid struggled.","Such was the scale of the devastation that international aid organizations struggled to respond.","So was the scale of devastation such that international aid struggled.","Such devastation was the scale of that international aid struggled."]','"Such was + the + noun phrase + that" = inversion with noun (not adjective).','hard'),
  (cid,11,77,'gap_fill','Such _____ the enthusiasm of the students _____ the professor extended the seminar by an hour.','was / that',NULL,'"Such was + noun phrase + that..." = inversion with noun.','hard'),

  -- BLOCK 12: little / few / in no way / at no time / under no circumstances
  (cid,12,78,'gap_fill','Little _____ (realize) that his research would eventually earn the Nobel Prize.','did he realize',NULL,'"Little + did + subject + infinitive" = inversion with little.','hard'),
  (cid,12,79,'multiple_choice','Which sentence uses "in no way" correctly with inversion?','In no way does this finding contradict the established theory.','["In no way this finding contradicts the established theory.","In no way does this finding contradict the established theory.","In no way contradicts this finding the established theory.","In no way did this finding not contradict the established theory."]','"In no way + does/did + subject + infinitive" = negative adverbial inversion.','hard'),
  (cid,12,80,'gap_fill','At no time _____ (the safety protocols / compromise) during the evacuation.','were the safety protocols compromised',NULL,'"At no time + were + subject + past participle" = negative temporal inversion.','hard'),
  (cid,12,81,'multiple_choice','Which sentence uses "under no circumstances" correctly?','Under no circumstances should participants be exposed to the substance without protective equipment.','["Under no circumstances participants should be exposed to the substance.","Under no circumstances should participants be exposed to the substance without protective equipment.","Under no circumstances participants are exposed to the substance.","No circumstances under should participants be exposed."]','"Under no circumstances + should/must + subject + infinitive" = modal inversion.','hard'),
  (cid,12,82,'gap_fill','On no account _____ (the data / share) with third parties without prior consent.','should the data be shared',NULL,'"On no account + should + subject + passive infinitive."','hard'),
  (cid,12,83,'multiple_choice','Identify the correct inversion: "The researchers were by no means convinced of the findings'' validity."','By no means were the researchers convinced of the findings'' validity.','["By no means were the researchers convinced of the findings'' validity.","By no means the researchers were convinced of the findings'' validity.","By no means are the researchers convinced of the findings'' validity.","By no means convinced were the researchers."]','"By no means + were + subject + adjective/participle" = inversion.','hard'),
  (cid,12,84,'gap_fill','Seldom _____ (a discovery / generate) such controversy so quickly.','has a discovery generated',NULL,'"Seldom + has + subject + past participle" = present perfect inversion.','hard'),

  -- BLOCK 13: neither / nor inversion
  (cid,13,85,'gap_fill','The first experiment failed, and neither _____ (the second).','did the second',NULL,'"Neither + did + subject" = agreement inversion for negative clauses.','hard'),
  (cid,13,86,'multiple_choice','Which sentence correctly uses "nor" with inversion?','The first hypothesis was not supported, nor was the second.','["The first hypothesis was not supported, nor the second was.","The first hypothesis was not supported, nor was the second.","The first hypothesis was not supported, nor did the second.","The first hypothesis was not supported, nor is the second."]','"Nor + was + subject" = inverted auxiliary after "nor."','hard'),
  (cid,13,87,'gap_fill','The first vaccine candidate did not produce the expected immune response, and nor _____ (the second candidate).','did the second candidate',NULL,'"And nor + did + subject" = negative continuation with inversion.','hard'),
  (cid,13,88,'multiple_choice','Transform: "She did not attend the conference, and he did not either." → inverted form.','She did not attend the conference, nor did he.','["She did not attend the conference, neither he did.","She did not attend the conference, nor did he.","She did not attend the conference, nor he attended.","She did not attend the conference, neither did he attended."]','"Nor + did + subject" = inverted auxiliary.','medium'),
  (cid,13,89,'gap_fill','Neither the lecture _____ (convince) the students, nor _____ (the reading material).','convinced / did the reading material',NULL,'"Neither + subject + verb" (first clause) + "nor + inverted" (second clause).','hard'),
  (cid,13,90,'multiple_choice','Which sentence combines two negatives with neither/nor correctly?','Neither did the control group show improvement, nor did the treatment group.','["Neither the control group show improvement, nor the treatment group did.","Neither did the control group show improvement, nor did the treatment group.","Neither the control group showed improvement, nor the treatment group.","Neither did the control group showed improvement, nor did the treatment group."]','Both clauses: "neither/nor + did + subject + base verb."','hard'),

  -- BLOCK 14: academic register and inversion
  (cid,14,91,'multiple_choice','Why do academic writers use inversion with negative adverbials?','To add rhetorical emphasis to negative or restrictive statements, elevating register.','["To avoid passive voice","To add rhetorical emphasis to negative or restrictive statements, elevating register.","Because it is grammatically required in academic English","To make sentences shorter"]','Inversion = elevated, formal register + emphasis on the negative/restrictive element.','hard'),
  (cid,14,92,'gap_fill','Rarely _____ (a study / achieve) such broad impact across multiple disciplines as Watson and Crick''s 1953 paper.','has a study achieved',NULL,'"Rarely + has + subject + past participle" = academic emphatic inversion.','hard'),
  (cid,14,93,'multiple_choice','Which sentence is most suitable for academic writing?','Not until the data had been independently verified did the journal agree to publish the findings.','["They only published after checking — the journal didn''t publish until they verified.","Not until the data had been independently verified did the journal agree to publish the findings.","The journal didn''t publish until the data had been verified.","Only when the data had been verified did the journal agree to publish (also correct — high register)."]','"Not until + past perfect + did + subject" = formal inversion. High academic register.','hard'),
  (cid,14,94,'gap_fill','Not only _____ (this study / confirm) the hypothesis, but it _____ (also / reveal) an entirely new phenomenon.','did this study confirm / also revealed',NULL,'"Not only + did + subject + base verb, but + subject + also + past simple" = parallel inversion.','hard'),
  (cid,14,95,'multiple_choice','Which pair correctly uses two different inversion types in one paragraph?','Rarely has such a comprehensive dataset been assembled. Not only did the study confirm the original hypothesis, but it also revealed significant subgroup differences.','["Rarely such a comprehensive dataset has been assembled. Not only the study confirmed the hypothesis.","Rarely has such a comprehensive dataset been assembled. Not only did the study confirm the original hypothesis, but it also revealed significant subgroup differences.","Rarely a dataset has been assembled. Not only did the study confirmed the hypothesis.","Rarely has such dataset assembled. Not only did the study confirming."]','Two inversion types: rarely + present perfect, not only + did.','hard'),

  -- BLOCK 15: TOEFL Reading
  (cid,15,96,'multiple_choice','[TOEFL Reading] "Never before had scientists observed a protein folding mechanism of such complexity." The inversion here emphasizes:','The unprecedented nature of the observation.','["A routine scientific observation","The future of protein research","The unprecedented nature of the observation.","The scientists'' error"]','"Never before had + subject + past participle" = emphatic inversion on the novelty of the event.','medium'),
  (cid,15,97,'gap_fill','[TOEFL Reading] "Hardly _____ (the experiment / begin) when the anomalous result appeared." Best inverted form?','had the experiment begun',NULL,'"Hardly + had + subject + past participle" = negative temporal inversion (almost immediately).','hard'),
  (cid,15,98,'multiple_choice','[TOEFL Reading] "So dramatic was the drop in biodiversity that ecologists declared a sixth mass extinction event underway." What does this inversion do?','Emphasizes the severity of the biodiversity loss by fronting the adjective.','["Introduces a contrast","Emphasizes the severity of the biodiversity loss by fronting the adjective.","Describes a future event","Reduces the formality of the claim"]','"So + adjective + was + subject + that" = emphatic fronting for dramatic rhetorical effect.','medium'),
  (cid,15,99,'gap_fill','[TOEFL Reading] "Not until the 20th century _____ (scientists / understand) the mechanism of inheritance." Best inverted form?','did scientists understand',NULL,'"Not until + time expression + did + subject + base verb" = temporal inversion.','hard'),
  (cid,15,100,'multiple_choice','[TOEFL Reading] A passage uses: "Under no circumstances should this compound be exposed to direct sunlight." This is an example of:','A negative adverbial triggering subject-auxiliary inversion for emphasis.','["A conditional clause","A passive construction","A negative adverbial triggering subject-auxiliary inversion for emphasis.","An infinitive of purpose"]','"Under no circumstances + should + subject + base verb" = modal inversion.','medium'),

  -- BLOCK 16: TOEFL Speaking production
  (cid,16,101,'production','[TOEFL Speaking — 45s] Discuss the importance of environmental protection using 3 inversion structures: rarely/never + present perfect, not only...but also, so + adjective + was + subject + that.','',NULL,'Rarely have the consequences of environmental neglect been felt so acutely as they are today. Not only has deforestation destroyed critical habitats, but it has also disrupted global weather patterns in ways that affect billions of people. So severe is the current rate of species loss that ecologists estimate we are losing biodiversity at a pace 1,000 times faster than the natural background rate. Under these circumstances, immediate and coordinated international action is not merely advisable but essential.','hard'),
  (cid,16,102,'production','[TOEFL Speaking — 45s] A professor argues that online education can never replace face-to-face learning. Agree or disagree using inversions: by no means, not only...but also, so limited is / was, nor.','',NULL,'By no means is online education a perfect replacement for face-to-face instruction. Not only does in-person learning allow for spontaneous interaction, but it also provides the social bonds that are central to the university experience. So limited was the engagement in some online courses during the pandemic that many students reported significant declines in motivation. Nor did virtual environments replicate the collaborative learning that occurs in physical spaces. That said, hybrid models may offer a promising middle ground.','hard'),

  -- BLOCK 17: TOEFL Writing production
  (cid,17,103,'production','[TOEFL Writing] Rewrite these sentences using inversion: (1) "The evidence was so clear that no further debate was necessary." (2) "The team had never experienced a setback of this magnitude before." (3) "The study not only confirmed the theory but also proposed a new model." (4) "The treatment was not effective, and the placebo was not effective either."','',NULL,'(1) So clear was the evidence that no further debate was necessary. (2) Never before had the team experienced a setback of this magnitude. (3) Not only did the study confirm the theory, but it also proposed a new model. (4) The treatment was not effective, nor was the placebo.','hard'),
  (cid,17,104,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "The consequences of climate change" using at least 4 inversion structures: never/rarely + present perfect, not only...but also, so + adjective + was/is, at no time / under no circumstances.','',NULL,'Never before in recorded history have global temperatures risen so rapidly as they have in the past five decades. So catastrophic are the projected consequences that climate scientists now speak of existential risk to coastal civilizations. Not only are sea levels rising at an accelerating pace, but rainfall patterns are also becoming increasingly unpredictable, threatening agricultural systems that feed billions. Under no circumstances can the international community afford to delay meaningful emission reductions beyond the current decade. Rarely has the scientific consensus on a global issue been so clear or so urgent. At no time in modern history have governments been presented with such unambiguous evidence and yet been so slow to act. The moral and economic costs of inaction now outweigh, by orders of magnitude, the costs of the transition to a low-carbon economy.','hard'),
  (cid,17,105,'production','[TOEFL Writing — Error Correction] Fix inversion errors: "So significant the discovery was that it transformed the field. Never the researchers before had encountered such data. Not only the study confirmed the hypothesis, but also revealed a new variable. In no way the findings should be generalized."','',NULL,'So significant was the discovery (was moves after so + adjective). Never before had the researchers encountered (before + had + subject + past participle). Not only did the study confirm the hypothesis, but it also revealed... (did + subject + base verb). In no way should the findings be generalized (should + subject + passive infinitive).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
